// FUNCTION: BFME2 0x004A82F5 size=150 name=?rva004A82F5@Rva004A82F5@@QAEXPAVObject@@HH@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x004A83D7 size=784 name=?applyTopplingForce@ToppleUpdate@@QAEXPBVCoord3D@@MI@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void ToppleUpdate::applyTopplingForce(const Coord3D *toppleDirection, Real toppleSpeed, UnsignedInt options)
{
	if (getObject()->isEffectivelyDead())
		return;

	const ToppleUpdateModuleData *d = (const ToppleUpdateModuleData *)getModuleData();
	if (toppleSpeed < d->m_minimumToppleSpeed)
		toppleSpeed = d->m_minimumToppleSpeed;

	Drawable *draw = getObject()->getDrawable();
	setWakeFrame(getObject(), UPDATE_SLEEP_NONE);

	if (d->m_killWhenStartToppling)
	{
		setWakeFrame(getObject(), UPDATE_SLEEP_FOREVER);
		getObject()->kill((DamageType)8, (DeathType)0);
		return;
	}

	m_toppleDirection = *toppleDirection;
	m_toppleDirection.normalize();
	TheScriptEngine->adjustToppleDirection(getObject(), &m_toppleDirection);

	m_angularVelocity = d->m_initialVelocityPercent * toppleSpeed;
	m_angularAcceleration = d->m_initialAccelPercent * toppleSpeed;
	m_toppleState = TOPPLE_FALLING;
	m_options = options;

	static NameKeyType nameKeySwayUpdate = TheNameKeyGenerator->nameToKey("SwayClientUpdate");
	Module **clientModules = draw->m_modules[1];
	if (clientModules)
	{
		while (*clientModules)
		{
			if ((*clientModules)->getModuleNameKey() == nameKeySwayUpdate)
				((SwayClientUpdate *)*clientModules)->m_unk0x22 = false;
			++clientModules;
		}
	}

	Real curAngleX = normalizeAngle(getObject()->getOrientation());
	Real toppleAngle = normalizeAngle(atan2(m_toppleDirection.y, m_toppleDirection.x));
	if (d->m_toppleLeftOrRightOnly)
	{
		toppleAngle = angleClosestTo(curAngleX + PI / 2, curAngleX - PI / 2, toppleAngle);
		m_toppleDirection.x = Cos(toppleAngle);
		m_toppleDirection.y = Sin(toppleAngle);
		TheAI->pathfinder()->RemoveObjectFromPathfindMap(getObject());
	}

	Real desiredAngleX = angleClosestTo(toppleAngle + PI / 2, toppleAngle - PI / 2, curAngleX);
	Real framesToTopple = ANGULAR_LIMIT / (m_angularVelocity * 2);
	m_numAngleDeltaX = Float_To_Long((Real)ToppleCRT::floor(framesToTopple));
	if (m_numAngleDeltaX < 1)
		m_numAngleDeltaX = 1;
	m_angleDeltaX = (desiredAngleX - curAngleX) / m_numAngleDeltaX;

	getObject()->setModelConditionState((ModelConditionFlagType)0);
	FXList::doFXObj(d->m_toppleFX, getObject(), 0);

	if (!d->m_stumpName.isEmpty())
	{
		const ThingTemplate *stumpTemplate = TheThingFactory->findTemplate(d->m_stumpName);
		CreateMask stumpMask;
		memset(&stumpMask, 0, sizeof(stumpMask));
		Object *stump = TheThingFactory->newObject(stumpTemplate, 0, &stumpMask, (ObjectID)0);
		if (stump)
		{
			stump->setPosition(getObject()->getPosition());
			stump->setOrientation(getObject()->getOrientation());
			m_stumpID = stump->getID();
			Drawable *ownerDraw = getObject()->getDrawable();
			if (ownerDraw && ownerDraw->m_conditionFlags.test(80))
				stump->setModelConditionState((ModelConditionFlagType)80);
		}
	}
}

// FUNCTION: BFME2 0x004A86E7 size=168 name=?xfer@Rva004A8091@@MAEXPAVXfer@@@Z evidence=?:placeholder tier=A
void ToppleUpdate::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	if (xfer->IsLightCRC())
		return;
	xfer->Version1();
	*xfer == m_angularVelocity;
	*xfer == m_angularAcceleration;
	*xfer == m_toppleDirection;
	xfer->XferRawBytes(&m_toppleState, 4);
	*xfer == m_angularAccumulation;
	*xfer == m_angleDeltaX;
	*xfer == m_numAngleDeltaX;
	*xfer == m_doBounceFX;
	*xfer == m_options;
	XferObjectID(xfer, &m_stumpID);
	*xfer == m_bounceDamping;
}

// FUNCTION: BFME2 0x004A878F size=1399 name=?update@ToppleUpdate@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger tier=A
UpdateSleepTime ToppleUpdate::update()
{
	if ((m_toppleState == TOPPLE_UPRIGHT) || (m_toppleState == TOPPLE_DOWN))
		return UPDATE_SLEEP_FOREVER;

	const ToppleUpdateModuleData *d = static_cast<const ToppleUpdateModuleData *>(m_moduleData);
	const Real VELOCITY_BOUNCE_LIMIT = 0.01f;
	const Real VELOCITY_BOUNCE_SOUND_LIMIT = 0.03f;

	Object *obj = getObject();
	if (m_numAngleDeltaX)
	{
		Matrix3D xfrm;
		xfrm = *obj->getTransformMatrix();
		xfrm.In_Place_Pre_Rotate_Z(m_angleDeltaX);
		obj->setTransformMatrix(&xfrm);
		--m_numAngleDeltaX;
	}

	Real curVelToUse = m_angularVelocity;
	if (m_angularAccumulation + curVelToUse > ANGULAR_LIMIT)
		curVelToUse = ANGULAR_LIMIT - m_angularAccumulation;

	Matrix3D xfrm;
	xfrm = *obj->getTransformMatrix();
	xfrm.In_Place_Pre_Rotate_X(-curVelToUse * m_toppleDirection.y);
	xfrm.In_Place_Pre_Rotate_Y(curVelToUse * m_toppleDirection.x);
	obj->setTransformMatrix(&xfrm);

	m_angularAccumulation += curVelToUse;
	if ((m_angularAccumulation >= ANGULAR_LIMIT) && (m_angularVelocity > 0))
	{
		Real bounceVelocity = d->m_bounceVelocityPercent - m_bounceDamping;
		Real minimumBounceVelocity = 0.05f;
		const Real *bounceVelocityToUse = (0.05f > bounceVelocity) ? &minimumBounceVelocity : &bounceVelocity;

		m_angularVelocity *= -(*bounceVelocityToUse);
		m_bounceDamping += 0.025f;

		if ((m_options & TOPPLE_OPTIONS_NO_BOUNCE) != 0 || fabs(m_angularVelocity) < VELOCITY_BOUNCE_LIMIT)
		{
			m_angularVelocity = 0;
			m_toppleState = TOPPLE_DOWN;

			if (d->m_killWhenFinishedToppling)
			{
				Rva004A82BAAttemptDamage(obj);
				if (d->m_reorientToppledRubble)
				{
					Vector3 pos;
					pos.X = 0;
					pos.Y = 0;
					pos.Z = obj->getGeometryInfo()->getMaxHeightAbovePosition();
					Matrix3D::Transform_Vector(*obj->getTransformMatrix(), pos, &pos);

					Coord3D tmp;
					tmp.x = pos.X;
					tmp.y = pos.Y;
					tmp.z = pos.Z;
					obj->setPosition(&tmp);
					obj->setOrientation(obj->getOrientation());
				}
			}

			if (d->m_killStumpWhenToppled)
			{
				Object *stump = TheGameLogic->findObjectByID(m_stumpID);
				if (stump)
					Rva004A82BAAttemptDamage(stump);
			}
		}
		else if (fabs(m_angularVelocity) >= VELOCITY_BOUNCE_SOUND_LIMIT)
		{
			if ((m_options & TOPPLE_OPTIONS_NO_FX) == 0)
				FXList::doFXObj(d->m_bounceFX, obj, 0);
		}
	}
	else
	{
		m_angularVelocity += m_angularAcceleration;
	}

	Drawable *draw = obj->getDrawable();
	if (draw)
		draw->setShadowsEnabled(false);

	return UPDATE_SLEEP_NONE;
}

